// Access input variables using input.config()
const inputData = input.config(); // This will fetch all your input variables (apikey)
const apikey = inputData.apikey; // API key from your inputs
const workspaceTable = base.getTable("Workspace IDs"); // Replace with your actual table name

let combinedCampaigns = []; // Initialize an array to store campaigns from all workspaces

// Main function to process each workspace
(async function main() {
  try {
    // Fetch all workspace IDs from the "Workspace IDs" table
    const workspaceRecords = await workspaceTable.selectRecordsAsync();
    const workspaceIDs = workspaceRecords.records.map(record => record.getCellValue("ID")); // Replace "ID" with the correct field name in your table

    // Log all workspace IDs
    console.log("Workspace IDs:", workspaceIDs);

    // Loop through each workspace ID
    for (const workspaceID of workspaceIDs) {
      console.log(`Switching to workspace ID: ${workspaceID}`);

      // Fetch request to switch workspace
      try {
        const switchResponse = await fetch('https://send.dulcy.io/api/workspaces/v1.1/switch-workspace', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${apikey}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            team_id: workspaceID
          })
        });

        if (!switchResponse.ok) {
          const errorText = await switchResponse.text();
          throw new Error(`HTTP error! Status: ${switchResponse.status}, Error: ${errorText}`);
        }

        const switchData = await switchResponse.json();
        console.log(`Successfully switched to workspace: ${workspaceID}`, switchData);

        // Fetch active campaigns for the current workspace
        console.log(`Fetching campaign data for workspace ID: ${workspaceID}`);
        const campaignResponse = await fetch('https://send.dulcy.io/api/campaigns?status=active', {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${apikey}`,
            'Content-Type': 'application/json'
          }
        });

        if (!campaignResponse.ok) {
          const errorText = await campaignResponse.text();
          throw new Error(`HTTP error! Status: ${campaignResponse.status}, Error: ${errorText}`);
        }

        const campaignData = await campaignResponse.json();
        console.log(`Campaign data for workspace ${workspaceID}:`, campaignData);

        // Combine campaign data into the main array
        if (Array.isArray(campaignData.data)) {
          combinedCampaigns = combinedCampaigns.concat(campaignData.data);
        }

      } catch (error) {
        console.error(`Error processing workspace ${workspaceID}:`, error.message || error);
      }
    }

    // Log the combined campaign data
    console.log("Combined Campaign Data:", combinedCampaigns);

    // Set combined campaign data as the output
    output.set("campaignDetails", JSON.stringify(combinedCampaigns)); // Output combined campaign details
    console.log("Output campaignDetails set successfully.");

  } catch (error) {
    console.error("Error fetching workspace IDs or processing workspaces:", error.message || error);
  }
})();

const inputData = input.config(); // Fetch input data
const apiKey = inputData.apikey; // API key passed in as an input
let campaignDetails = inputData.campaignDetails; // Array of campaign details from the script output
const table = base.getTable("Campaigns"); // Replace "Campaigns" with your Airtable table name

console.log("Input Data:", inputData); // Log input data for debugging

// Ensure campaignDetails is an array by parsing it if necessary
if (typeof campaignDetails === "string") {
    try {
        campaignDetails = JSON.parse(campaignDetails); // Parse the string into a JSON array
    } catch (error) {
        console.error("Error parsing campaignDetails:", error);
        throw new Error("campaignDetails is not a valid JSON array.");
    }
}

// Check if campaignDetails is a valid array
if (!Array.isArray(campaignDetails) || campaignDetails.length === 0) {
    console.error("Campaign Details is empty or not in the correct format.");
    throw new Error("Campaign Details is empty or invalid.");
}

(async function main() {
    try {
        // Fetch all existing records in the table
        const existingRecords = await table.selectRecordsAsync();

        for (const campaign of campaignDetails) {
            try {
                // Reformat created_at and updated_at to ensure proper ISO 8601 format
                campaign.created_at = new Date(campaign.created_at).toISOString();
                campaign.updated_at = new Date(campaign.updated_at).toISOString();

                // Check if the campaign already exists in the table
                const existingRecord = existingRecords.records.find(
                    record => record.getCellValue("ID") === campaign.id
                );

                if (existingRecord) {
                    // Update the existing record
                    await table.updateRecordAsync(existingRecord.id, {
                        "Name": campaign.name,
                        "Emails Sent": campaign.emails_sent,
                        "Unique Replies": campaign.unique_replies,
                        "Bounced": campaign.bounced,
                        "Progress": campaign.completion_percentage/100,
                        "Interested": campaign.interested,
                        "Total Leads Contacted": campaign.total_leads_contacted,
                        "Created At": campaign.created_at,
                        "Updated At": campaign.updated_at,
                    });
                    console.log(`Updated record for campaign: ${campaign.name}`);
                } else {
                    // Create a new record
                    await table.createRecordAsync({
                        "ID": campaign.id,
                        "Name": campaign.name,
                        "Emails Sent": campaign.emails_sent,
                        "Unique Replies": campaign.unique_replies,
                        "Bounced": campaign.bounced,
                        "Progress": campaign.completion_percentage/100,
                        "Interested": campaign.interested,
                        "Total Leads Contacted": campaign.total_leads_contacted,
                        "Created At": campaign.created_at,
                        "Updated At": campaign.updated_at,
                    });
                    console.log(`Created record for campaign: ${campaign.name}`);
                }
            } catch (error) {
                console.error(`Error processing campaign ${campaign.name}:`, error.message || error);
            }
        }
    } catch (error) {
        console.error("Error fetching existing records or processing campaigns:", error.message || error);
    }
})();
